"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";

/**
 * Admin controls for the NxLabs catalogue (GameMod).
 *
 * Deliberately thin for Phase 1 — per the owner's ask, this is "view rows,
 * toggle active/see upstreamOk", not a full mod editor. The REAL upstream
 * facts (icon, downloads, license, verifiedAt, upstreamOk/upstreamNote) are
 * never hand-edited here; they only ever come from scripts/verify-gamemods.ts
 * reading the mod's actual source. `active` is the one thing an admin sets by
 * hand — pulling a mod from the catalogue without waiting for (or overriding)
 * a verification pass, e.g. a licensing complaint or a request from the
 * source. Mirrors lib/actions-gameplans.ts's adminToggleGamePlan exactly,
 * with the shared recordAudit() writer instead of an ad hoc db.auditLog.create.
 */

type Result = { error?: string; ok?: boolean };

export async function adminToggleGameModActive(id: string): Promise<Result> {
  const admin = await requireArea("billing");
  const mod = await db.gameMod.findUnique({ where: { id } });
  if (!mod) return { error: "Not found." };
  const next = !mod.active;
  await db.gameMod.update({ where: { id }, data: { active: next } });
  await recordAudit(admin.id, "gamemod.toggle", `${mod.gameFamily}/${mod.slug} → active=${next}`);
  revalidatePath("/admin/game-mods");
  revalidatePath("/mods");
  return { ok: true };
}

/**
 * Explicit "mark as no longer supported" — separate from `active` because the
 * two answer different questions: `active` is "should the catalogue offer
 * this at all", `upstreamOk` is "does the source still have it". An admin
 * flipping this by hand covers the gap between verify runs (a customer
 * reports a dead link today, the next scheduled verify isn't for hours).
 */
export async function adminSetGameModUpstreamOk(id: string, upstreamOk: boolean, note: string): Promise<Result> {
  const admin = await requireArea("billing");
  const mod = await db.gameMod.findUnique({ where: { id } });
  if (!mod) return { error: "Not found." };
  await db.gameMod.update({
    where: { id },
    data: {
      upstreamOk,
      upstreamNote: upstreamOk ? null : note.trim() || "Marked unsupported by an admin.",
      verifiedAt: new Date(),
    },
  });
  await recordAudit(admin.id, "gamemod.upstream", `${mod.gameFamily}/${mod.slug} → upstreamOk=${upstreamOk}`);
  revalidatePath("/admin/game-mods");
  revalidatePath("/mods");
  return { ok: true };
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES } from "../lib/mod-install-support";
import { controlSpec } from "../lib/game-control";
import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
import type { Job } from "@prisma/client";

/**
 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
 * state recorded in `ServerMod` rows:
 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
 *
 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
 *
 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
 * mod is installed when nothing was written to their server:
 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
 *    FAILED with a clear reason — never silently "INSTALLED".
 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
 *    message. A change we did NOT apply is a failure and must say so.
 */

const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-mods] notify failed", e);
  }
}

export async function gameModSync(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game mod sync: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const pending = await db.serverMod.findMany({
    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
    include: { mod: true },
  });
  if (pending.length === 0) return;

  const installedNames: string[] = [];
  const removedNames: string[] = [];
  const failedNames: string[] = [];

  for (const sm of pending) {
    const removing = sm.status === "REMOVING";
    try {
      if (SANDBOX) {
        // Dev simulation — no VM mutation.
        if (removing) {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
          installedNames.push(sm.mod.name);
        }
        continue;
      }

      if (!REAL_ENABLED) {
        // Honest failure: nothing was applied. Do NOT report success.
        await db.serverMod.update({
          where: { id: sm.id },
          data: {
            status: "FAILED",
            error:
              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
          },
        });
        failedNames.push(sm.mod.name);
        continue;
      }

      // REAL path — install/remove over SSH via the per-source adapter.
      const modRow: ModRowFull = {
        gameFamily: sm.mod.gameFamily,
        source: sm.mod.source,
        sourceId: sm.mod.sourceId,
        slug: sm.mod.slug,
        name: sm.mod.name,
        url: sm.mod.url,
        variant: server.gameVariant ?? null,
        appliesTo: sm.mod.appliesToVariant ?? null,
      };
      const result =
        sm.mod.source === "steam_workshop"
          ? await workshopSync(server, sm.mod.gameFamily, serverId)
          : removing
          ? await removeModReal(server, modRow)
          : await installModReal(server, modRow);

      if (result.ok) {
        if (removing) {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({
            where: { id: sm.id },
            data: { status: "INSTALLED", version: result.version ?? null, error: null },
          });
          installedNames.push(sm.mod.name);
        }
      } else {
        await db.serverMod.update({
          where: { id: sm.id },
          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
        });
        failedNames.push(sm.mod.name);

